<template><section v-if="products.length" class="technical-compatibility"><header><h3>Compatibilidad de la proforma</h3><button type="button" :disabled="busy" @click="$emit('analyze')">{{assembly?'Evaluar ensamblaje':'Evaluar compatibilidad'}}</button></header><label>Evaluar como<select :value="assembly?'assembly':'target'" :disabled="busy" @change="$emit('assembly',$event.target.value==='assembly')"><option value="assembly">Una computadora por armar</option><option value="target">Accesorios para un equipo de destino</option></select></label><p>{{assembly?'Las piezas se comparan entre si. No necesitas un modelo de computadora de destino.':'Indica el modelo del equipo de destino en los datos del caso.'}}</p><p v-if="results.some(r=>r.status==='incompatible')" class="compatibility-blocker">Hay piezas incompatibles. Revisa las filas rojas antes de armar el equipo.</p><div class="compatibility-table"><table><thead><tr><th>Producto</th><th>RAM / memoria</th><th>Estado</th><th>Conflicto o fundamento</th></tr></thead><tbody><tr v-for="product in products" :key="product.key" :class="'compatibility-row-'+result(product).status"><td><strong>{{product.name}}</strong><small v-if="product.model">{{product.model}}</small></td><td class="compatibility-memory">{{result(product).memory || 'No aplica / sin confirmar'}}</td><td><span :class="result(product).reason?'compatibility-'+result(product).status:'compatibility-unevaluated'">{{result(product).reason?label(result(product).status):'Sin evaluar'}}</span></td><td>{{result(product).reason || 'Esta pieza no tiene un resultado individual. Pulsa Evaluar nuevamente.'}}<details><summary>Ver diferencias y opciones</summary><dl><dt>Diferencias tecnicas</dt><dd>{{result(product).differences || 'Sin determinar'}}</dd><dt>Modelos o familias compatibles</dt><dd>{{result(product).models || 'Sin confirmar'}}</dd><dt>Falta comprobar</dt><dd>{{result(product).requirements || 'Sin datos adicionales'}}</dd></dl><p v-if="product.specs">{{product.specs}}</p><button type="button" :disabled="busy" @click="$emit('investigate',product)">Buscar detalles e imagenes</button></details></td></tr></tbody></table></div></section></template>
<script>
export default {props:{products:{type:Array,default:()=>[]},results:{type:Array,default:()=>[]},busy:Boolean,assembly:{type:Boolean,default:true}},methods:{result(product){return this.results.find(row=>String(row.key)===String(product.key))||{status:'pending'}},label(status){return {compatible:'Compatible',incompatible:'Incompatible',pending:'Falta informacion'}[status]||'Pendiente de verificar'}}}
</script>
<style>.technical-compatibility{margin:18px 0}.technical-compatibility>header{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.technical-compatibility h3{font-size:18px;margin:0}.technical-compatibility>label{font-size:13px;display:block;margin:12px 0}.technical-compatibility select{width:100%;margin-top:5px}.technical-compatibility>p{font-size:12px;color:#536e8e;margin:8px 0}.technical-compatibility .compatibility-blocker{background:#ffe3e8;color:#a21c38;padding:10px;border-radius:8px}.compatibility-table{overflow:auto;border:1px solid #dce4ef;border-radius:10px}.compatibility-table table{width:100%;border-collapse:collapse;min-width:480px;font-size:12px}.compatibility-table th{background:#eef2fa;text-align:left;padding:9px}.compatibility-table td{vertical-align:top;padding:9px;border-top:1px solid #dce4ef}.compatibility-table td:first-child{width:25%}.compatibility-table .compatibility-memory{font-weight:600;color:#324e78;min-width:90px}.compatibility-table small{display:block;margin-top:4px}.compatibility-table td>span{display:inline-block;padding:4px 7px;border-radius:6px;white-space:nowrap;font-size:11px}.compatibility-compatible{background:#d9f4e8;color:#116345}.compatibility-incompatible{background:#ffe3e8;color:#a21c38}.compatibility-unevaluated{background:#e9edf4;color:#42536b}.compatibility-pending{background:#fff2cc;color:#795617}.compatibility-row-incompatible{background:#fff6f7}.compatibility-table details{margin-top:6px}.compatibility-table summary{color:#5145ad;cursor:pointer}.compatibility-table dt{margin-top:8px}.compatibility-table dd{margin:3px 0;white-space:pre-wrap;overflow-wrap:anywhere}.compatibility-table button{font-size:12px!important;padding:7px 9px!important}</style>
